import copy

from .store import JsonStore, identifier, integer
from .query import tags, search_docs


_EVENT_FIELDS = {'id', 'version', 'body', 'tags', 'deleted'}


def _validated_events(events):
    if not isinstance(events, list) or len(events) > 1000:
        raise ValueError('events must be a list of at most 1000 documents')
    seen = set()
    for event in events:
        if not isinstance(event, dict) or set(event) != _EVENT_FIELDS:
            raise ValueError('event shape')
        identifier(event['id'])
        integer(event['version'], high=1_000_000)
        if not isinstance(event['body'], str) or len(event['body']) > 10000:
            raise ValueError('body')
        if type(event['deleted']) is not bool:
            raise ValueError('deleted')
        tags(event['tags'])
        if event['id'] in seen:
            raise ValueError('duplicate document')
        seen.add(event['id'])
    # Preserve both event order and tag order in the immutable receipt.
    return copy.deepcopy(events)


class DocumentIndex:
    def __init__(self, path):
        self.store = JsonStore(path)

    def apply_batch(self, tenant, batch_id, events):
        identifier(tenant)
        identifier(batch_id)
        events = _validated_events(events)

        def action(data):
            state = data.setdefault(tenant, {'docs': {}, 'batches': {}})
            if batch_id in state['batches']:
                if state['batches'][batch_id] != events:
                    raise ValueError('batch conflict')
                return False

            for event in events:
                old = state['docs'].get(event['id'])
                if old is not None:
                    if event['version'] < old['version']:
                        continue
                    if event['version'] == old['version']:
                        if event != old:
                            raise ValueError('version conflict')
                        continue
                # Tombstones participate in version checks just like live docs.
                state['docs'][event['id']] = event
            state['batches'][batch_id] = events
            return True

        return self.store.transact(action)

    def set_policy(self, tenant, revision, blocked_tags):
        """Replace a tenant's exclusions without changing documents or receipts."""
        identifier(tenant)
        integer(revision, high=1_000_000)
        # Validate even stale updates. Only policy tags are order-insensitive;
        # sorting also detaches the caller's list from the persisted policy.
        blocked = sorted(tags(blocked_tags))

        def action(data):
            state = data.setdefault(tenant, {'docs': {}, 'batches': {}})
            old = state.get('policy')
            if old is not None:
                if revision < old['revision']:
                    return False
                if revision == old['revision']:
                    if blocked != old['blocked_tags']:
                        raise ValueError('policy revision conflict')
                    return False
            state['policy'] = {'revision': revision, 'blocked_tags': blocked}
            return True

        return self.store.transact(action)

    def get(self, tenant, doc_id):
        identifier(tenant)
        identifier(doc_id)
        return copy.deepcopy(
            self.store.data.get(tenant, {}).get('docs', {}).get(doc_id)
        )

    def search(self, tenant, query, limit=10, required_tags=None):
        identifier(tenant)
        state = self.store.data.get(tenant, {})
        # Missing policies in stage-0 stores mean no exclusions; no migration
        # or rewriting of existing documents and batch receipts is needed.
        blocked = state.get('policy', {}).get('blocked_tags', ())
        return search_docs(state.get('docs', {}), query, limit, required_tags, blocked)

